# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    errors = []
    def pointer(path, key):
        return path + '/' + str(key).replace('~', '~0').replace('/', '~1')
    def visit(schema, value, path):
        kind = schema['type']
        types = {'object': dict, 'array': list, 'string': str, 'integer': int,
                 'number': (int, float), 'boolean': bool, 'null': type(None)}
        valid = isinstance(value, types[kind])
        if not valid:
            errors.append({'path': path, 'code': 'type'})
            return
        if kind == 'object':
            properties = schema.get('properties', {})
            for key in schema.get('required', []):
                if key not in value:
                    errors.append({'path': pointer(path, key), 'code': 'required'})
            for key, child in value.items():
                if key in properties:
                    visit(properties[key], child, pointer(path, key))
                elif not schema.get('additional', True):
                    errors.append({'path': pointer(path, key), 'code': 'additional'})
        elif kind == 'array':
            if len(value) < schema.get('min_items', 0):
                errors.append({'path': path, 'code': 'min_items'})
            if 'items' in schema:
                for index, child in enumerate(value):
                    visit(schema['items'], child, pointer(path, index))
        elif kind == 'string' and len(value) < schema.get('min_length', 0):
            errors.append({'path': path, 'code': 'min_length'})
    visit(payload['schema'], payload['value'], '')
    return sorted(errors, key=lambda error: (error['path'], error['code']))

